        fs.writeFileSync(outPath, JSON.stringify(shard, null, 2));
        count++;

        if (count % 1000 === 0) {
            console.log(`Processed ${count} articles...`);
        }
    }

    console.log(`✅ [HUSK] Cleaning Complete. Total processed: ${count}`);
