  threshold: z.number().min(0),
  /** Direction guard so no one misreads the threshold. */
  closerIs: z.enum(["lower", "higher"]),
  /** Where this number came from — refuses "magic constant" drift. */
  calibration: z.object({
    calibrated: z.boolean(),
    corpus: z.string().nullable(),
    corpusSize: z.number().int().positive().nullable(),
    date: z.string().nullable(),
    note: z.string().nullable(),
  }),
});
export type SilencePolicy = z.infer<typeof SilencePolicy>;

/**
 * Dimensionality carries a rationale, because "why this many dims" is
 * the hardest-won lesson on the project (over-embedding static data).
 * The schema makes you state it, so the mistake can't silently return.
 */
export const Dimensionality = z.object({
  dims: z.number().int().positive(),
  rationale: z.string().min(1),
  /** true only where sequence encodes causality (temporal path). */
  temporalAxis: z.boolean(),
});
export type Dimensionality = z.infer<typeof Dimensionality>;

/** A single pipeline: one data type, refined one way, served one way. */
export const DomainPipeline = z.object({
  /** Stable key an agent selects by, e.g. "legal-corpus". */
  id: z.string().regex(/^[a-z0-9-]+$/, "id must be kebab-case"),
  description: z.string().min(1),
  status: z.enum(["proven", "operational", "wiring", "planned"]),

  dataType: z.string().min(1),
  geometry: GeometryKind,
  processor: Processor,
  dimensionality: Dimensionality,

  store: z.object({
    kind: StoreKind,
    /** collection name / index path / pack id */
    location: z.string().min(1),
    /** embedding model if the store needs one; null for simhash/faiss-fingerprint */
    embedModel: z.string().nullable(),
    /**
     * WIRE (folded from v2 pipeline.json). The reachable endpoint of the
     * store. null when the store is a local file (vault-index, faiss-pack).
     * Example: "http://100.113.215.46:6333" for a Qdrant collection.
     * This is infra fact — only Joe can verify it.
     */
    endpoint: z.string().url().nullable().optional(),
    /**
     * WIRE. Vector distance metric the store is configured with, if it's a
     * vector store. Distinct from silence.signal: this is how the STORE
     * indexes, silence.signal is how the RECEPTACLE gates. They usually
     * agree, but recording both catches the case where they don't.
     */
    distanceMetric: z.enum(["cosine", "dot", "euclid"]).nullable().optional(),
  }),

  /**
   * WIRE (folded from v2). How this pipeline's corpus is (re)built. Lets an
   * agent regenerate a collection without hunting for the script — and is
   * exactly what the three HOT pipelines need pointed at a low-D re-ingest.
   */
  ingest: z
    .object({
      /** script/command that ingests this domain, e.g. "scripts/ingest-finance-heatmap.ts" */
      script: z.string().min(1),
      /** processor/refinery entrypoint if different from the script */
      refineryStage: z.string().nullable(),
    })
    .optional(),

  /** The vehicle built to run on this fuel. */
  receptacle: z.object({
    /** what consumes it: a query entrypoint, an MCP, an A2A endpoint */
    kind: z.enum(["cli-query", "http-service", "mcp", "a2a", "harness-tui"]),
    /** path or URL — where the receptacle lives */
    ref: z.string().min(1),
    /**
     * WIRE (folded from v2). Named tools/endpoints this receptacle exposes,
     * e.g. ["consult_statute","verify_negotiability"] for ArbiterOS, or
     * ["/health","/api/legal/query"] for LawLibra. Omitted = not yet folded
     * from v2 (distinct from [] which means "confirmed none").
     */
    tools: z.array(z.string()).optional(),
  }),

  silence: SilencePolicy,

  /**
   * When what's RUNNING differs from what's INTENDED, record both instead
   * of picking one. This is the anti-fragmentation field: it stops the
   * next agent from "resolving" a conflict by guessing. Populated only
   * where a live artifact (test, payload, running service) contradicts
   * the design intent.
   */
  liveVsTarget: z
    .object({
      live: z.string().min(1),   // what a real artifact proves is running now
      target: z.string().min(1), // what the design intends
      evidence: z.string().min(1), // the artifact that proves 'live'
      resolved: z.boolean(),
    })
    .optional(),

  const elapsed = Date.now() - startMs;
  console.log(`💎 [ORCHESTRATOR] Index built: ${this.indexedCount} active shards (${skipped} skipped) in ${elapsed}ms`);
}

private rebalanceHotBuffer() {
  const sorted = [...this.index].sort((a, b) => b.frequency - a.frequency);
  const limit = Math.ceil(this.indexedCount * this.HOT_THRESHOLD_PERCENT);
  this.hotRingBuffer.clear();
  for (let i = 0; i < limit; i++) {
    if (sorted[i]) {
      this.hotRingBuffer.set(sorted[i].shardId, sorted[i]);
    }
  }
  console.log(`🔥 [HUSK] Hot Buffer Rebalanced: ${this.hotRingBuffer.size} critical landmarks pinned.`);
}

private async finishRetrieval(selected: any[], totalStart: number, indexStart: number): Promise<QueryResult> {
  const indexLookupMs = Date.now() - indexStart;
  let cacheMisses = 0;
  const contextShards: any[] = [];

  for (const { entry } of selected) {
    let shard = this.cache.get(entry.shardId);
    if (!shard) {
      cacheMisses++;
      const filePath = path.join(this.config.shardDir, `${entry.shardId}.json`);
      if (fs.existsSync(filePath)) {
        const raw = JSON.parse(fs.readFileSync(filePath, "utf-8"));
        shard = { id: raw.id, content: raw.content, source: raw.source };
        this.cache.put(shard);
      }
    }
    if (shard) contextShards.push(shard);
  }

  const citations = selected.map(r => ({
    shardId: r.entry.shardId,
    source: r.entry.source,
    hammingRatio: r.drift.hammingRatio,
    contentPreview: r.entry.contentPreview
  }));

  const sourceTexts = contextShards.map(s => ({
    shardId: s.id,
    source: s.source,
    fullText: s.content
  }));

  return {
    answer: null,
    citations,
    sourceTexts,
    metrics: {
      indexLookupMs,
      cacheMisses,
      inferenceMs: 0,
      totalMs: Date.now() - totalStart,
      shardsEvaluated: this.index.length,
      shardsSelected: selected.length
    },
    silenced: false,
    mode: "retrieve"
  };
}

/**
 * SANITIZATION: L2-Normalization Gate
 * Prevents "Qubit Poison" (variance blowouts) in 3072-D space.
 * Enforces all vectors onto the Unit Sphere.
 */
private normalizeL2(vector: number[]): number[] {
  const magnitude = Math.sqrt(vector.reduce((sum, val) => sum + val * val, 0));
  if (magnitude === 0) return new Array(vector.length).fill(0);
  const normalized = vector.map(val => val / magnitude);

  // Safety Check: Verify Unit Sphere projection
  const newMag = Math.sqrt(normalized.reduce((sum, val) => sum + val * val, 0));
  if (Math.abs(newMag - 1.0) > 0.0001) {
    console.warn(`⚠️ [QUBIT_ALARM] Normalization Drift: ${newMag}`);
  }
  return normalized;
}

/**
 * Query the knowledge vault.
 * 
 * 1. SimHash the query
 * 2. Rank all shards by Hamming distance
 * 3. Select top-N within threshold
 * 4. Return verified source text with citations
 * 
 * This is the FAITH-LESS core: no generation, no hallucination.
 * If the shard doesn't contain it, the agent stays silent.
 */
async retrieve(question: string): Promise<QueryResult> {
  if (!this.initialized) {
    await this.buildIndex();
  }

  const totalStart = Date.now();

  // ─── Step 1: SimHash the query ──────────────────────────────
  const indexStart = Date.now();
  const querySignature = this.guard.simHash128FromText(question, "corpus");

  // ─── Step 1.5: O(1) HOT PATH ────────────────────────────────
  for (const hot of this.hotRingBuffer.values()) {
    const drift = this.queryGuard.evaluateDrift(querySignature, hot.signature);
    if (drift.hammingRatio < 0.10) {
      console.log(`⚡ [HOT_PATH] Direct Hit: ${hot.shardId}`);
      hot.frequency++;
      // If we hit the hot path, we can skip the full index search
      // Note: For simplicity, we bypass the slice/filter and just return the hot hit
      const selected = [{ entry: hot, drift }];
      return this.finishRetrieval(selected, totalStart, indexStart);
    }
  }

  // ─── Step 2: Rank shards by Hamming distance ────────────────
  const ranked: Array<{ entry: IndexEntry; drift: DriftResult }> = [];

