function stripHtml(html: string): string {
    // Basic HTML stripping logic
    return html
        .replace(/<script\b[^>]*>([\s\S]*?)<\/script>/gmi, "")
        .replace(/<style\b[^>]*>([\s\S]*?)<\/style>/gmi, "")
        .replace(/<[^>]+>/g, " ")
