def build_points(shards: list[dict], vectors: list[list[float]], id_start: int, repo_name: str) -> list[PointStruct]:
    points = []
    for i, (shard, vec) in enumerate(zip(shards, vectors)):
        points.append(PointStruct(
            id=id_start + i,
            vector=vec,
            payload={
                "shard_id":    shard["id"],
