export type EmbeddingVector = Float64Array;

export type NormalizationResult =
  | { ok: true; vector: EmbeddingVector; magnitude: number }
  | { ok: false; error: string; code: "ZERO_VECTOR" | "NAN_DETECTED" | "INVALID_DIMENSIONS" | "MAGNITUDE_DRIFT" };

const EXPECTED_DIMENSIONS = 3072;
const MAGNITUDE_TOLERANCE = 1e-6; // For verifying already-normalized vectors

/**
 * Computes the ℓ₂ magnitude (Euclidean norm) of a vector.
 * Uses Kahan summation to reduce floating-point accumulation error
 * on high-dimensional vectors.
 */
function l2Magnitude(vec: EmbeddingVector): number {
  let sum = 0.0;
  let compensation = 0.0; // Kahan compensation variable

  for (let i = 0; i < vec.length; i++) {
    const term = vec[i] * vec[i] - compensation;
    const temp = sum + term;
    compensation = (temp - sum) - term;
    sum = temp;
  }

  return Math.sqrt(sum);
}

/**
 * ℓ₂-Normalize a raw embedding vector.
 * Returns a NEW Float64Array — never mutates the input.
 * 
 * Enforces:
 * - Correct dimensionality (3072)
 * - No NaN/Infinity values
 * - Non-zero magnitude
 */
export function l2Normalize(raw: number[] | Float64Array): NormalizationResult {
  if (raw.length !== EXPECTED_DIMENSIONS) {
    return {
      ok: false,
      error: `Expected ${EXPECTED_DIMENSIONS} dimensions, got ${raw.length}`,
      code: "INVALID_DIMENSIONS"
    };
  }

  const vec = raw instanceof Float64Array ? raw : new Float64Array(raw);

  // Scan for NaN/Infinity before computing magnitude
  for (let i = 0; i < vec.length; i++) {
    if (!Number.isFinite(vec[i])) {
      return {
        ok: false,
        error: `NaN or Infinity detected at dimension ${i}`,
        code: "NAN_DETECTED"
      };
    }
  }

  const magnitude = l2Magnitude(vec);

  if (magnitude === 0) {
    return {
      ok: false,
      error: "Zero vector rejected — no semantic content",
      code: "ZERO_VECTOR"
    };
  }

  const normalized = new Float64Array(vec.length);
  for (let i = 0; i < vec.length; i++) {
    normalized[i] = vec[i] / magnitude;
  }

  return { ok: true, vector: normalized, magnitude };
}

/**
 * Verify that a vector is already ℓ₂-normalized.
 * Used at query time as a fast guard — if this fails,
 * the vector was tampered with or corrupted in transit.
 */
export function verifyNormalized(vec: EmbeddingVector): boolean {
  if (vec.length !== EXPECTED_DIMENSIONS) return false;
  const mag = l2Magnitude(vec);
  return Math.abs(mag - 1.0) < MAGNITUDE_TOLERANCE;
}

/**
 * Contract-level validation for embedding payloads.
 * Combines dimensionality, NaN, and normalization checks
 * into a single gate.
 */
export function validateEmbeddingPayload(payload: unknown): NormalizationResult {
  if (!payload || typeof payload !== "object") {
    return { ok: false, error: "Payload must be an object", code: "INVALID_DIMENSIONS" };
  }

  const p = payload as Record<string, unknown>;

  if (!Array.isArray(p.vector) && !(p.vector instanceof Float64Array)) {
    return { ok: false, error: "Missing or invalid 'vector' field", code: "INVALID_DIMENSIONS" };
  }

  return l2Normalize(p.vector as number[] | Float64Array);
}

import { writeFileSync, mkdirSync } from "node:fs";
import { loadQueries } from "./corpus.js";
import { scoreOne, aggregate } from "./metrics.js";
import { huskAdapter, naiveBaseline } from "./adapter.js";
import type { Metrics, RetrievalAdapter, ScoredResult } from "./types.js";

/**
 * Usage:
 *   npx tsx src/run-eval.ts corpus/queries.jsonl
 *   npx tsx src/run-eval.ts corpus/queries.jsonl --sweep 4,8,12,16,20
 *
 * Outputs: results/results.json, results/report.md
 * Deterministic: no sampling, no judge model, fixed query order.
 */

async function runAdapter(
  adapter: RetrievalAdapter,
  queriesPath: string,
  threshold?: number
): Promise<{ metrics: Metrics; results: ScoredResult[] }> {
  const queries = loadQueries(queriesPath);
  const results: ScoredResult[] = [];
  for (const q of queries) {
    const r = await adapter.query(q, threshold);
    results.push(scoreOne(q, r));
  }
  return { metrics: aggregate(adapter.name, results, threshold), results };
}

function pct(x: number): string {
  return (x * 100).toFixed(1) + "%";
}

function renderReport(all: Metrics[]): string {
  const rows = all
    .map(
      (m) =>
        `| ${m.adapterName} | ${m.threshold ?? "—"} | ${pct(m.trueAnswerRate)} | ${pct(
          m.trueSilenceRate
        )} | ${pct(m.falseSilenceRate)} | ${pct(m.falseAnswerRate)} | ${
          m.meanLatencyMs ? m.meanLatencyMs.toFixed(0) + "ms" : "—"
        } |`
    )
    .join("\n");

  return `# Silence-First RAG Benchmark

Generated ${new Date().toISOString()} — fully offline, deterministic (evidence-matched scoring, no judge model).

| System | Threshold | True Answer | True Silence | False Silence | False Answer | Mean Latency |
|---|---|---|---|---|---|---|
${rows}

**Reading this table:** False Answer is the hallucination surface — the rate at
which the system fabricates when the corpus cannot support an answer. False
Silence is the over-refusal cost. A useful system drives False Answer toward
zero without letting False Silence climb.
`;
}

async function main() {
  const queriesPath = process.argv[2];
  if (!queriesPath) {
    console.error("Usage: tsx src/run-eval.ts <queries.jsonl> [--sweep t1,t2,...]");
    process.exit(1);
  }
  const sweepArg = process.argv.indexOf("--sweep");
  const thresholds =
    sweepArg > -1
      ? process.argv[sweepArg + 1].split(",").map(Number)
      : [undefined];

  const allMetrics: Metrics[] = [];
  const allResults: Record<string, ScoredResult[]> = {};

  for (const t of thresholds) {
    const { metrics, results } = await runAdapter(huskAdapter, queriesPath, t);
    allMetrics.push(metrics);
    allResults[`${huskAdapter.name}@${t ?? "default"}`] = results;
  }

  // Baseline once (no gate, threshold irrelevant)
  try {
    const { metrics, results } = await runAdapter(naiveBaseline, queriesPath);
    allMetrics.push(metrics);
    allResults[naiveBaseline.name] = results;
  } catch {
    console.warn("Baseline adapter not wired — skipping (wire it for the comparison table).");
  }

  mkdirSync("results", { recursive: true });
  writeFileSync("results/results.json", JSON.stringify({ metrics: allMetrics, results: allResults }, null, 2));
  writeFileSync("results/report.md", renderReport(allMetrics));
  console.log(renderReport(allMetrics));
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

