        hammingRatio: c.hammingRatio,
        preview: c.contentPreview
      })),
      silenced: retrieval.silenced,
      durationMs: Date.now() - retrieveStart
    };
    steps.push(retrieveStep);

    // ── Step 2: Silence gate ──────────────────────────────────────────────────
    if (retrieval.silenced && role.silencePolicy === "strict") {
      return {
        sessionId,
        role: role.id,
        sector: role.sector,
        steps,
        finalResponse: null,
        silenced: true,
