import * as crypto from "crypto";

export interface SimHashSignature {
  /** The 128-bit signature as a BigInt */
  signature: bigint;
  /** Source shard ID for audit trail */
  shardId: string;
  /** Timestamp of signature generation */
  generatedAt: string;
