  "version": "1.0.0-mvp",
  "description": "Sovereign tokenless memory — Faith-Less retrieval over massive datasets. No fine-tuning required.",
  "api": {
    "port": $API_PORT,
    "routes": {
      "query":   "POST /query",

    // Simple word-level tokenization: lowercase, split on whitespace
    const words = text.toLowerCase().split(/\s+/).filter(w => w.length > 0);
    const tokens = new Uint32Array(words.length);
    for (let i = 0; i < words.length; i++) {
      tokens[i] = this.fnv1a32(words[i]);
