const SOURCE_EXTENSIONS = new Set([
  ".ts", ".tsx", ".js", ".jsx",
  ".py", ".go", ".rs", ".lua", ".sol",
  ".java", ".kt", ".cs",
  ".cpp", ".cc", ".c", ".h", ".hpp",
