    punct_ratio = punct_count / max(1, len(words))
    punct_score = min(1.0, punct_ratio * 10)  # normalize: ~0.1 punct/word is good

    score = (unique_ratio * 0.5) + (punct_score * 0.3) - (noise_penalty * 0.2)
