def temporal_cat(t: list[float], t_minus1: list[float], t_start: list[float]) -> list[float]:
    """
    T || T-1 || T-start → 3072-D sovereign temporal vector.
    Dimensions:
        [0..1023]    T        current shard content
        [1024..2047] T-1      previous shard (drift)
