NOISE_PATTERNS = re.compile(
    r'(skip to|click here|sign up|subscribe|newsletter|cookie|privacy policy|'
    r'terms of use|all rights reserved|share this|back to top|breadcrumb|'
    r'search results|page \d+ of \d+)',
