    } catch (err) {
      console.error("⚠️ [PULSE] Failed to write audit log:", err);
    }
  }

  /**
   * Get the orchestrator for external query access.
   */
  getOrchestrator(): LandmarkOrchestrator {
    return this.orchestrator;
  }
