def strip_html(html: str) -> str:
    text = SCRIPT_RE.sub(" ", html)
    text = STYLE_RE.sub(" ", text)
    text = TAG_RE.sub(" ", text)
    text = ENTITY_RE.sub(" ", text)
    text = BOILERPLATE_RE.sub(" ", text)
    text = WHITESPACE.sub(" ", text)
    return text.strip()

