def chunk_text(text: str, words_per_chunk: int) -> list[str]:
    words = text.split()
    chunks = []
    for i in range(0, len(words), words_per_chunk):
        chunk = " ".join(words[i : i + words_per_chunk])
        if len(chunk.split()) >= MIN_WORDS:
            chunks.append(chunk)
    return chunks

