    if (fs.existsSync(filePath)) {
      try {
        const raw = JSON.parse(fs.readFileSync(filePath, "utf-8"));
        return {
          id: shardId,
          content: raw.content ?? raw.text ?? raw.chunk ?? "",
          title: raw.title ?? shardId,
          source: raw.source ?? "",
