            else:
                buckets[bit] -= 1

    sig = 0
    for bit in range(64):
        if buckets[bit] > 0:
            sig |= (1 << bit)
    return sig

def hamming_ratio(a: int, b: int, bits: int = 64) -> float:
    """Hamming distance as ratio of total bits."""
    xor = a ^ b
    distance = bin(xor).count('1')
    return distance / bits

