  const indexed: Array<{ dim: number; absVal: number; val: number }> = [];
  for (let i = 0; i < vector.length; i++) {
    indexed.push({ dim: i, absVal: Math.abs(vector[i]), val: vector[i] });
  }
  indexed.sort((a, b) => b.absVal - a.absVal);

