      signal: ac.signal,
    });
    clearTimeout(tid);
    if (!res.ok) throw new Error(`Ollama embed failed: ${res.status}`);
    const body = await res.json() as { embeddings: number[][] };
    const vecs = body.embeddings;
    if (!vecs || vecs.length === 0) throw new Error("Ollama returned no embeddings");
    return vecs[0]!;
  } finally {
    clearTimeout(tid);
  }
