    k: c.k,
    d: c.originalDimensions,
    dims: c.components.map(x => x.dim),
    vals: c.components.map(x => Number(x.val.toFixed(8))),
    energy: Number(c.energyRetained.toFixed(6)),
    ratio: Number(c.compressionRatio.toFixed(6))
