  const components: Array<{ dim: number; val: number }> = [];
  for (let i = 0; i < raw.dims.length; i++) {
    components.push({ dim: raw.dims[i], val: raw.vals[i] });
  }

  return {
    shardId: raw.id,
    k: raw.k,
    originalDimensions: raw.d,
    components,
    compressionRatio: raw.ratio,
    energyRetained: raw.energy
  };
