  q: EvalQuery,
  threshold?: number
): Promise<PipelineResponse> {
  const orch = await getOrchestrator(threshold);
  const t0 = performance.now();
  const result = await orch.retrieve(q.text); // FAITH-LESS mode
  const latencyMs = performance.now() - t0;

  if (result.silenced) {
