SHARD_DIR    = "/Volumes/ARCHIVE/Emergency_Information/WhiteGlove_Agent_Husk/brain/shards/shattered"
OUTPUT_DIR   = "/Volumes/ARCHIVE/Emergency_Information/WhiteGlove_Agent_Husk/exports"
