  ollamaModel: string;
  /** Ollama API base URL */
  ollamaUrl: string;
  /** SimHash Hamming threshold for shard-to-shard drift detection (tight) */
  similarityThreshold: number;
  /** SimHash Hamming threshold for query-to-shard matching (wider).
